      "**2단계 - 가상 메모리 조정 (이용자 안내):**\n① 시스템 속성 → 고급 → 성능 옵션 → 가상 메모리\n② 권장 크기의 2배 수준으로 늘려 재부팅",
      "**3단계 - DirectX 최신화 (이용자 안내):**\n① Microsoft 공식 DirectX 최신 런타임 설치",
