    causes: [
      "게임 파일이 손상되었거나 최신 패치가 불완전하게 적용된 경우",
      "그래픽 드라이버가 오래된 경우",
      "백신·보안 프로그램이 실행 파일을 차단하는 경우",
      "메모리 부족(특히 저사양 PC)"
    ],

    solutions: [
      "**1단계 - 최소 사양 확인과 Steam 재시작 (PUBG 공식 안내):**\n① PUBG 지원 문서는 먼저 내 PC가 게임의 최소 사양을 충족하는지 확인하라고 안내합니다(오래된 문서이므로 최신 권장 사양은 공식 페이지에서 확인하세요).\n② Steam을 완전히 종료했다가 다시 실행합니다. 최근 윈도우 업데이트를 설치했다면 특히 도움이 된다고 안내합니다.",
      "**2단계 - 게임 파일 무결성 검사 (PUBG 공식 안내):**\n① Steam을 열고 '라이브러리'에서 PUBG(배틀그라운드)를 마우스 오른쪽 버튼으로 눌러 '속성'을 선택합니다.\n② '로컬 파일'(영문 Local Files) 탭을 누릅니다.\n③ '게임 파일 무결성 검사'를 누르고 끝날 때까지 기다립니다.",
      "**3단계 - 윈도우 업데이트 (PUBG 공식 안내):**\n① 시작 → 설정 → Windows 업데이트(Windows 10은 업데이트 및 보안)에서 '업데이트 확인'을 누릅니다.\n② 설치할 업데이트가 있으면 설치하고 컴퓨터를 다시 시작합니다.",
      "**4단계 - 그래픽 등 드라이버 최신화 (PUBG 공식 안내):**\n① 그래픽카드와 사용 중인 다른 하드웨어의 드라이버를 모두 최신으로 맞추라고 안내합니다.\n② NVIDIA나 AMD 지원 페이지에서 내 그래픽카드에 맞는 최신 드라이버를 받아 설치합니다.",
      "**5단계 - Steam과 게임을 관리자 권한으로 실행 (PUBG 공식 안내):**\n① 파일 탐색기에서 C:\Program Files (x86)\Steam 으로 가서 Steam.exe를 마우스 오른쪽 버튼으로 눌러 '관리자 권한으로 실행'을 선택합니다(Steam 초기화 오류에도 도움이 된다고 안내).\n② 이어서 ...\steamapps\common\Battlegrounds\TslGame\Binaries\Win64 폴더에서 TslGame.exe를 마우스 오른쪽 버튼으로 눌러 '관리자 권한으로 실행'을 선택합니다. 설치 위치가 다르면 그 폴더 기준으로 찾으세요.",
      "**6단계 - 설치 위치 점검 (PUBG 공식 안내):**\n① 문서는 게임을 윈도우가 설치된 같은 하드디스크에 두라고 안내합니다. SSD에 설치하면 일반 하드디스크보다 훨씬 빠르다고도 안내합니다.",
      "**7단계 - 저사양 메모리 옵션 (문서 외 일반 점검):**\n① Steam 라이브러리 → PUBG 속성 → 시작 옵션에 -lowmemory 입력 후 재시작(RAM이 부족한 환경에서 크래시가 줄 수 있다는 이용자 보고에 근거)",
      "**8단계 - 보안 프로그램 예외 추가 (문서 외 일반 점검):**\n① 백신 프로그램에서 TslGame.exe, PUBG.exe를 예외로 등록",
      "**9단계 - 그래도 안 되면 지원 문의 (PUBG 공식 안내):**\n① 위로도 해결되지 않으면 문제 화면의 스크린샷이나 영상, 덤프 파일을 준비해 PUBG 플레이어 지원에 문의하라고 안내합니다."
    ],

