      "**2단계 - 부품 발열과 그래픽 옵션 (카카오게임즈 공식 안내):**\n① 그래픽카드와 CPU 같은 주요 부품의 발열이 정상 범위인지 확인합니다.\n② 게임 안 그래픽 옵션을 낮춰 봅니다.",
      "**3단계 - 인터넷 회선 점검과 유선 전환 (카카오게임즈 공식 안내):**\n① 핑이 높으면 로딩이 걸릴 수 있으니 인터넷 회선을 점검합니다. 회선 점검이 필요하면 사용 중인 통신사(ISP)에 문의합니다.\n② 공유기를 쓰고 있다면 무선 대신 이더넷(LAN 케이블)으로 바꿔 봅니다.",
