    overview: "Windows Defender 방화벽이나 타사 백신이 리그 오브 레전드의 서버 통신을 차단해 접속·패치가 진행되지 않는 경우입니다.",

    causes: ["방화벽이 클라이언트·게임 실행 파일을 차단 목록에 올린 경우", "타사 백신이 실시간 감시로 통신을 가로채는 경우", "네트워크 어댑터 드라이버가 오래되어 연결이 불안정한 경우"],

    solutions: [
      "**1단계 - 방화벽 제품을 최신으로 업데이트 (Riot 공식 안내):**\n① Riot은 여러 방화벽 제조사에 연락해 롤을 무해한 프로그램으로 등록해 두었고, 방화벽을 최신 상태로 업데이트하면 예외가 자동으로 적용될 수 있다고 안내합니다.\n② 사용 중인 방화벽·보안 제품 제조사의 지원 사이트에서 최신 업데이트를 받습니다. 일부 제품은 구독이 있어야 최신 정의를 받을 수 있습니다.",
      "**2단계 - Windows 방화벽을 잠시 꺼서 원인 확인 (Riot 공식 안내):**\n① Riot은 가장 빠른 확인 방법으로 방화벽을 임시로 끄는 것을 안내합니다. 원인 확인용 임시 조치이며 확인이 끝나면 다시 켜야 합니다.\n② 윈도우 키를 눌러 '제어판'을 열고 '시스템 및 보안' → 'Windows 방화벽'을 누릅니다.\n③ 왼쪽의 'Windows 방화벽 사용 또는 사용 안 함'을 누릅니다(관리자 암호 확인 창이 뜰 수 있습니다).\n④ 각 네트워크 위치에서 'Windows 방화벽 사용 안 함'을 선택하고 확인한 뒤 롤을 실행해 봅니다.\n⑤ 정상 작동하면 방화벽을 다시 켜고, 아래 3단계처럼 예외를 추가합니다.",
      "**3단계 - 타사 방화벽은 완전히 제거해 확인 (Riot 공식 안내):**\n① Riot은 타사 방화벽은 끄기만 해도 계속 연결을 막는 경우가 있어 완전히 제거한 뒤 확인하라고 안내합니다.\n② 원인을 찾은 뒤에는 방화벽을 다시 설치하고 롤 네트워크 통신을 허용하도록 설정합니다.\n③ 공유기 자체의 방화벽을 끄는 것은 위험하니 Riot도 신중하라고 안내합니다. 임시로만 확인하세요.",
      "**4단계 - 백신 예외 등록 (문서 외 일반 점검):**\n① 사용 중인 백신 프로그램에서 리그 오브 레전드 설치 폴더를 예외로 등록",
      "**5단계 - 네트워크 어댑터 드라이버 업데이트 (문서 외 일반 점검):**\n① 장치 관리자 → 네트워크 어댑터 → 드라이버 업데이트 실행"
    ],

    officialSource: { title: "Riot Games Support: Advanced Connections Troubleshooting Guide", url: "https://support.riotgames.com/en-us/league-of-legends/connectivity/advanced-connections-troubleshooting-guide" },
