    causes: ["설치 드라이브를 변경한 직후 업데이트가 특정 지점에서 멈추는 경우", "배틀넷 앱 캐시가 손상된 경우", "네트워크 연결이 불안정해 다운로드가 반복 재시도되는 경우"],

    solutions: ["**1단계 - 배틀넷 앱의 스캔 및 복구 실행 (문서 외 일반 점검):**\n① 배틀넷 앱 설정 → 게임 설치/업데이트 → 스캔 및 복구 실행", "**2단계 - 배틀넷 앱 재시작 (문서 외 일반 점검):**\n① 배틀넷 앱을 완전히 종료 후 재실행하여 업데이트 재개", "**3단계 - 네트워크 안정성 확인 (문서 외 일반 점검):**\n① 유선 연결로 전환한 뒤 업데이트 재시도", "**4단계 - 재설치 (문서 외 일반 점검):**\n① 위 방법으로도 반복되면 게임을 완전히 삭제한 뒤 재설치"],

