    overview: "패치 이후 플레이 버튼을 눌러도 실행되지 않고 계속 업데이트 상태로 돌아가는 증상으로, 블리자드 포럼에 다수 보고된 사례입니다.",

    causes: ["런처의 업데이트 확인 절차가 특정 단계에서 멈추는 경우", "런처 캐시가 손상되어 최신 버전 인식에 실패하는 경우", "네트워크 연결이 불안정해 패치 파일 검증이 반복 실패하는 경우"],

    solutions: ["**1단계 - 자동 업데이트 설정 확인 (문서 외 일반 점검):**\n① 런처 설정에서 '자동 업데이트 적용 금지'가 켜져 있다면 해제", "**2단계 - 시간을 두고 재시도 (문서 외 일반 점검):**\n① 몇 분 정도 기다린 뒤 실행 버튼을 다시 클릭", "**3단계 - 캐시 폴더 삭제 후 재시작 (Blizzard 공식 안내):**\n① 키보드에서 Ctrl + Shift + Esc를 눌러 작업 관리자를 엽니다.\n② 프로세스 목록에서 Agent, Battle.net(블리자드 배틀넷 앱), 실행 중인 게임 항목을 하나씩 선택하고 '작업 끝내기'를 누릅니다.\n③ 키보드에서 윈도우 키 + R을 눌러 '실행' 창을 열고, 입력칸에 C:\ProgramData\ 를 입력한 뒤 Enter를 누릅니다. 이 폴더는 숨김 폴더라 탐색기에서 안 보일 수 있으니 꼭 직접 입력하세요.\n④ 열린 폴더 목록에서 Battle.net 폴더를 마우스 오른쪽 버튼으로 눌러 '삭제'를 선택합니다.\n⑤ Battle.net을 다시 실행하고 게임 업데이트를 진행해 문제가 사라졌는지 확인합니다.\n⑥ 같은 문제가 계속되면 컴퓨터를 재시작한 뒤 ③~④를 한 번 더 합니다.\n⑦ 이 작업 뒤 게임 버튼이 '플레이' 대신 '설치'로 보여도 게임이 지워진 것이 아닙니다. Battle.net이 설치 위치를 잊었을 뿐이니, 그 게임 화면에서 이미 설치된 폴더를 직접 지정해 주세요(Blizzard 안내).\n⑧ 마지막으로 컴퓨터를 재시작한 뒤 Battle.net에서 게임 실행 버튼을 다시 눌러 봅니다.", "**4단계 - 재설치 (문서 외 일반 점검):**\n① 위 방법으로도 반복되면 게임을 완전히 삭제한 뒤 재설치"],

