      "**4단계 - 인터넷 연결 안정성 점검 (Steam 공식 안내):**\n① 불안정한 연결은 다운로드가 잘못되고 게임 서버 연결 시간 초과를 일으킬 수 있다고 안내합니다. 연결 품질 점검 사이트로 안정성을 확인합니다.",
      "**5단계 - VPN·P2P 프로그램 종료와 서버 구분 (문서 외 일반 점검):**\n① VPN·트래픽 제한·P2P 프로그램을 종료\n② 다른 Steam 기능도 안 되는지 확인하고, 서버 점검이 아니라면 오류 시각과 네트워크 환경을 기록해 Steam 지원에 문의"
