    overview: "Windows에 내장된 Xbox Game Bar는 녹화·스크린샷을 위해 여러 게임에서 백그라운드로 함께 동작합니다. 다른 오버레이 프로그램과 함께 켜져 있으면 단축키가 충돌하거나, 오버레이 자체가 프레임을 갉아먹는 경우가 있습니다.",

