    solutions: [
      "**1단계 - 게임 바 요건과 설정 확인 (Xbox 공식 안내):**\n① Xbox 지원 문서는 2024년 10월부터 Xbox 앱과 Game Bar의 일부 기능이 제대로 작동하려면 Windows 10 22H2 이상이 필요하다고 안내합니다. 설정 → 시스템 → 정보 → Windows 사양 → 버전에서 확인합니다.\n② Windows N 버전을 쓴다면 추가 소프트웨어(미디어 기능 팩)를 내려받아야 할 수 있다고 안내합니다.\n③ 설정 → 게임 → 게임 바에서 기능이 켜져 있는지, 다른 프로그램과 단축키가 겹치지 않는지 확인합니다.",
      "**2단계 - 다른 오버레이 정리 (문서 외 일반 점검):**\n① GeForce Experience·Discord·백신 등 다른 오버레이 프로그램을 하나씩 꺼서 어떤 조합에서 충돌하는지 확인",
      "**3단계 - 게임 바 자체를 끄기 (문서 외 일반 점검):**\n① 녹화·스크린샷 기능이 필요 없다면 설정 → 게임 → 게임 바를 꺼서 오버레이 자체를 비활성화",
      "**4단계 - 백그라운드 프로세스 재시작 (문서 외 일반 점검):**\n① 작업 관리자에서 Xbox 관련 프로세스를 종료한 뒤 재부팅"
    ],

