    solutions: [
      "**1단계 - 사전 컴파일 대기 (문서 외 일반 점검):**\n① 게임에 '셰이더 사전 컴파일' 단계가 있다면 건너뛰지 말고 완료까지 대기\n② 없는 게임이라면 처음 1~2판은 스터터링을 감안하고 플레이, 이후 캐시가 쌓이면 완화되는지 비교",
      "**2단계 - 셰이더 캐시 재생성 (문서 외 일반 점검):**\n① 그래픽 드라이버 제어판(NVIDIA 제어판·AMD 소프트웨어)에서 셰이더 캐시 크기를 '무제한' 또는 큰 값으로 설정\n② 문제가 지속되면 드라이버 캐시 폴더를 비우고 게임을 다시 실행해 캐시를 새로 생성",
      "**3단계 - 디스크 공간 확보 (문서 외 일반 점검):**\n① 설치 드라이브에 여유 공간이 충분한지 확인\n② SSD 사용을 권장(HDD는 컴파일된 캐시 기록 속도가 느려 스터터링이 더 오래 지속될 수 있음)",
      "**4단계 - 드라이버 버전 비교 (문서 외 일반 점검):**\n① 최신 드라이버에서 유독 심하다면 이전 안정 버전과 비교\n② 게임 커뮤니티에 같은 드라이버 버전에서 보고된 사례가 있는지 확인"
    ],
    officialSource: { title: "EA Help: PC 그래픽 문제 해결", url: "https://help.ea.com/kr/help/pc/pc-graphics-troubleshooting/" },
