    solutions: [
      "**1단계 - 서비스 중단 여부 확인 (블리자드 공식 안내):**\n① 블리자드는 접속 문제가 있을 때 먼저 블리자드 고객지원(블리자드CS) 트위터(X) 계정에 서비스 중단 소식이 있는지 보라고 안내합니다.\n② 중단 소식이 없으면 아래 단계로 넘어갑니다. 점검·장애 공지는 이 페이지 아래 '접속이 안 될 때 서버 점검부터 확인' 항목에서도 볼 수 있습니다.",
      "**2단계 - Battle.net 앱에서 지역·계정 확인 (블리자드 공식 안내):**\n① Battle.net 데스크톱 앱을 열고 왼쪽에서 스타크래프트 II를 선택합니다.\n② 게임 실행(플레이) 버튼 바로 위에 올바른 지역과 계정이 선택돼 있는지 확인합니다.\n③ 다른 지역이 선택돼 있으면 올바른 지역으로 바꾼 뒤 다시 접속합니다.",
      "**3단계 - 게임 복구 실행 (블리자드 공식 안내):**\n① Battle.net 앱에서 스타크래프트 II를 선택하고, 게임 실행 버튼 근처의 톱니바퀴(옵션)를 누릅니다.\n② '스캔 및 복구'를 누르고 검사가 끝날 때까지 기다립니다. 손상된 파일은 다시 내려받습니다(메뉴 이름은 앱 버전에 따라 조금 다를 수 있습니다).\n③ 끝나면 게임을 다시 실행합니다.",
      "**4단계 - 바이러스 검사 (블리자드 공식 안내):**\n① 블리자드는 바이러스나 악성코드 감염을 제거하기 위해 바이러스 검사를 하라고 안내합니다.\n② 시작 버튼을 누르고 'Windows 보안'을 검색해 실행합니다.\n③ '바이러스 및 위협 방지'를 누르고 '빠른 검사'를 실행합니다. 결과에 위협이 나오면 안내에 따라 조치합니다.",
      "**5단계 - Battle.net 앱 재시작 (문서 외 일반 점검):**\n① 작업 관리자에서 Battle.net·StarCraft II 프로세스를 모두 종료\n② Battle.net 앱 재실행 후 재로그인",
      "**6단계 - 네트워크 초기화 (문서 외 일반 점검):**\n① 명령 프롬프트(관리자)에서 ipconfig /flushdns 실행\n② 공유기 재시작 후 재접속",
      "**7단계 - VPN·프록시 해제 (문서 외 일반 점검):**\n① 사용 중인 VPN을 끄고 재시도\n② 인터넷 속성의 프록시 설정도 사용 안 함으로 변경",
      "**8단계 - 방화벽 예외 확인 (문서 외 일반 점검):**\n① Windows Defender 방화벽에서 Battle.net·StarCraft II 실행 파일이 허용되어 있는지 확인"
    ],

